<script setup lang="ts">
import { ref, watch } from 'vue'
import { Heart, Moon, Clock3, Sparkles, ArrowUpRight, Settings2, MessageCircle, RefreshCw, Send, Link2 } from '@lucide/vue'
import { api, put, requestId, session } from '../lib/api'
import { useResource } from '../lib/resource'
import { choice, confirmAction, date, field, notify, openForm, run } from '../lib/ui'
import type { Profile } from '../types'
import PageHeading from '../components/PageHeading.vue'
import ResourceState from '../components/ResourceState.vue'
import EmptyState from '../components/EmptyState.vue'
import FeishuConnect from '../components/FeishuConnect.vue'
import QQPrivateRhythm from '../components/QQPrivateRhythm.vue'
import QQOutreachLog, {type Outreach} from '../components/QQOutreachLog.vue'
import '../styles/companion.css'
interface Config { enabled:boolean; active_start:string; active_end:string; quiet_start:string; quiet_end:string; min_interval_minutes:number; daily_limit:number; chat_cooldown_minutes:number; channels:string[]; interests:string[]; share_bilibili:boolean; profile_id:string|null }
interface Activity {id:string;status:string;reason:string;body:string;created_at:number;sources:{id:string;title:string;url:string}[];deliveries:{channel:string;status:string;error:string}[]}
interface View {config:Config;activities:Activity[];followups?:Outreach[];timezone:string;state:{next_check_at:number;last_sent_at:number|null};channels:Record<string,boolean>;astrbot:{bound:boolean;session:string}}
const defaults:Config={enabled:false,active_start:'09:00',active_end:'22:00',quiet_start:'23:00',quiet_end:'08:00',min_interval_minutes:180,daily_limit:3,chat_cooldown_minutes:45,channels:['inapp'],interests:[],share_bilibili:false,profile_id:null}
const names:Record<string,string>={inapp:'站内通知',astrbot:'AstrBot 私聊',feishu:'飞书',feishu_app:'飞书机器人（应用）',onebot:'QQ 个人号（NapCat）',serverchan:'Server酱'}
const statuses:Record<string,string>={sent:'已送达',queued:'等待投递',partial:'部分送达',skip:'安静待着',failed:'未完成',unknown:'结果待核实',cancelled:'已取消',evaluating:'正在想聊些什么',dispatching:'正在投递'}
const reasons:Record<string,string>={nothing_to_share:'这次没有合适的新内容，先安静待着。',model_error:'模型暂时未完成判断，稍后按计划再检查。',processing_error:'处理未完成，请检查模型与渠道配置。',settings_changed:'设置已更新，这次没有继续发送。',quiet_hours:'现在是免打扰时间。',outside_active_hours:'还没到活动时段。',chat_cooldown:'刚聊过，先留一点空间。',calendar_busy:'日程忙碌，暂缓打扰。',daily_limit:'今天已经达到消息上限。',min_interval:'离上一次分享还不够久。',awaiting_reply:'最近互动较少，延长安静的时间。',duplicate:'这件事已经分享过了。',disabled:'主动陪伴已关闭。',evaluation_interrupted:'上次判断中断了，未继续发送。',sharing:'有一点想与你分享。'}
const draft=ref<Config>({...defaults}), interests=ref(''), saving=ref(false), saveError=ref('')
const {data,loading,error,load}=useResource(async()=>{
 const [view,profiles,integrations]=await Promise.all([api<View>('/companion'),api<Profile[]>('/profiles'),api<Record<string,any>>('/integrations')]);return {view,profiles,integrations}
},{view:{config:defaults,activities:[],timezone:'Asia/Shanghai',state:{next_check_at:0,last_sent_at:null},channels:{inapp:true},astrbot:{bound:false,session:''}} as View,profiles:[] as Profile[],integrations:{} as Record<string,any>})
watch(data,v=>{draft.value={...v.view.config,channels:[...v.view.config.channels],interests:[...v.view.config.interests]};interests.value=v.view.config.interests.join('\n')})
async function save(){saving.value=true;saveError.value='';try{await put('/companion',{...draft.value,profile_id:draft.value.profile_id||null,interests:interests.value.split(/[,，\r\n]+/).map(s=>s.trim()).filter(Boolean)});notify('陪伴设置已保存，将按计划检查');await load()}catch(e){saveError.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}
async function qq(){const latest=await api<Record<string,any>>('/integrations'),c=latest.qq||{};openForm({title:'连接个人 QQ',description:'只处理绑定主人的私聊，对话与记忆留在主库。与群接入共用 OneBot 连接及回调地址。',fields:[
 choice('private_enabled','个人 QQ 私聊',[['false','关闭'],['true','开启']],!!c.private_enabled),{...field('owner_qq','主人 QQ 号',c.owner_qq||'','text',true),readonly:!!c.owner_qq},field('bot_qq','机器人 QQ 号',c.bot_qq||'','text',true),field('url','OneBot HTTP 地址',c.onebot?.url||'','url',true),field('token','OneBot 访问 Token',c.onebot?.token||'','password'),{...field('secret','事件回调密钥',c.inbound?.secret||requestId()+requestId(),'text',true),wide:true,hint:'首次保存前复制，填入 NapCat HTTP 客户端的 Token；只填密钥，不加 Bearer。保存后只显示掩码。'},choice('profile_id','私聊模型',[['','沿用默认模型'],...data.value.profiles.map(p=>[p.id,p.name] as [string,string])],c.profile_id||'')
],save:async v=>{await put('/integrations',{...latest,qq:{...c,private_enabled:v.private_enabled==='true',owner_qq:v.owner_qq.trim(),bot_qq:v.bot_qq.trim(),onebot:{...c.onebot,url:v.url,token:v.token},inbound:{secret:v.secret},profile_id:v.profile_id||null}});notify('个人 QQ 设置已保存');await load()}})}
function unbind(){confirmAction('解除 AstrBot 绑定？','尚未投递的主动消息会取消。以后可以从私聊重新绑定。',async()=>{await api('/integrations/astrbot/binding',{method:'DELETE',body:JSON.stringify({session:data.value.view.astrbot.session})});notify('AstrBot 已解绑');await load()})}
const origin=window.location.origin
</script>
<template>
 <PageHeading title="有话想和你说" description="记得你的近况，偶尔分享一点新发现。没有合适的内容，就安静待着。" eyebrow="A LITTLE COMPANY, AT YOUR PACE"><span :class="['tag',data.view.config.enabled?'green':'neutral']"><Heart :size="13" />{{ data.view.config.enabled?'陪伴已开启':'陪伴未开启' }}</span></PageHeading>
 <ResourceState :loading="loading" :error="error" @retry="load">
  <div class="companion-layout"><form class="panel companion-form" @submit.prevent="save">
   <div class="companion-form-title"><span class="stat-icon green"><Heart :size="22" /></span><div><h2>按你的节奏来</h2><p>在合适的时候，带来一点轻松的陪伴。</p></div></div>
   <label class="companion-toggle"><input v-model="draft.enabled" type="checkbox" /><span><strong>允许灵犀主动找我聊</strong><small>沿用你选择的模型、人设与主库记忆，消息会留在活动记录中。</small></span></label>
   <div class="companion-model"><label for="companion-model">陪伴模型</label><select id="companion-model" v-model="draft.profile_id"><option :value="null">沿用默认模型</option><option v-for="p in data.profiles" :key="p.id" :value="p.id">{{ p.name }}</option></select></div>
   <fieldset><legend><Clock3 :size="17" />什么时候可以找你</legend><p>以下时间按你的时区 {{ data.view.timezone }}。活动时段内也会遵守免打扰时间；日程忙碌时会暂缓。</p><div class="companion-fields"><label>活动开始<input v-model="draft.active_start" type="time" required /></label><label>活动结束<input v-model="draft.active_end" type="time" required /></label><label>免打扰开始<input v-model="draft.quiet_start" type="time" required /></label><label>免打扰结束<input v-model="draft.quiet_end" type="time" required /></label></div><small>开始和结束相同时，活动时段表示全天，免打扰时段表示关闭。</small></fieldset>
   <fieldset><legend><Moon :size="17" />留一点空间</legend><div class="companion-fields"><label>每天最多几条<input v-model.number="draft.daily_limit" type="number" min="1" max="12" required /></label><label>两次主动消息至少间隔（分钟）<input v-model.number="draft.min_interval_minutes" type="number" min="30" max="1440" required /></label><label class="full">刚聊过后，安静一会儿（分钟）<input v-model.number="draft.chat_cooldown_minutes" type="number" min="15" max="1440" required /></label></div><small>这些是上限，不是每天必须发满的数量。长时间没有互动时，灵犀会减少打扰。</small></fieldset>
   <fieldset><legend><Sparkles :size="17" />想聊些什么</legend><label>你的兴趣<textarea v-model="interests" rows="3" placeholder="例如：猫咪、摄影、Rust、旅行" /></label><small>一行一个，也可以用逗号分开；最多 8 个，每个 40 字。</small><label class="companion-toggle compact"><input v-model="draft.share_bilibili" type="checkbox" /><span><strong>偶尔分享 B 站新发现</strong><small>优先分享 B 站书房中读过的字幕心得，附原视频链接。暂无阅读记录时使用已配置的联网搜索。</small></span></label></fieldset>
   <fieldset><legend><Send :size="17" />发到哪里</legend><div class="companion-channels"><label v-for="(name,key) in names" :key="key"><input v-model="draft.channels" type="checkbox" :value="key" :disabled="!data.view.channels[key] && !draft.channels.includes(key)" /><span>{{ name }}<small v-if="!data.view.channels[key]">待配置</small></span></label></div><p>飞书等渠道可在 <RouterLink to="/settings?tab=channels">通知设置</RouterLink> 中配置。AstrBot 需先完成绑定。</p></fieldset>
   <p v-if="saveError" role="alert" class="form-error">{{ saveError }}</p><div class="companion-save"><button class="button" :disabled="saving">{{ saving?'正在保存…':'保存陪伴设置' }}</button><small>保存后按计划运行，不会立即发消息。</small></div>
  </form>
  <aside class="companion-aside"><section class="companion-note"><span class="companion-orbit" aria-hidden="true">✧</span><Heart :size="26" /><h2>偶尔一句问候，<br />也留足安静的空间。</h2><p>每 15 分钟检查一次是否合适，<br />有值得分享的内容才会来找你。</p><div v-if="data.view.config.enabled" class="companion-next"><Clock3 :size="14" />下次检查 {{ date(data.view.state.next_check_at) }}</div></section>
   <section class="panel companion-connect"><div class="section-heading"><h3>连接个人 QQ</h3><MessageCircle :size="19" /></div><span :class="['tag',data.integrations.qq?.private_enabled?'green':'neutral']">{{ data.integrations.qq?.private_enabled?'已配置':'未连接' }}</span><p>通过 NapCat 连接灵犀。绑定主人的私聊可以继续对话，也能接收主动消息。</p><button class="button secondary" @click="run(qq)"><Settings2 :size="15" />{{ data.integrations.qq?.private_enabled?'管理个人 QQ':'配置 NapCat' }}</button><details><summary>查看回调地址</summary><code>{{ origin }}/api/v2/qq/inbound/{{ session.user?.id }}</code><p>NapCat HTTP 客户端的 Token 填回调密钥，消息格式选 array；机器人 QQ 登录在 NapCat 完成。</p></details></section>
   <section class="panel companion-connect"><div class="section-heading"><h3>连接 AstrBot</h3><Link2 :size="18" /></div><span :class="['tag',data.view.astrbot.bound?'green':'neutral']">{{ data.view.astrbot.bound?'已绑定':'未连接' }}</span><p>AstrBot 接收平台消息，灵犀负责对话、记忆和任务。主动消息送回绑定的私聊。</p><ol><li>部署 AstrBot，安装项目中的灵犀插件。</li><li>私聊发送 <code>/lingxi 身份</code>，将身份、API 地址和账号 Token 填入插件后台。</li><li>在对应私聊发送 <code>/lingxi 绑定</code>，然后选择 AstrBot 推送渠道。</li></ol><code>{{ origin }}/api/v2</code><p>Token 在 <RouterLink to="/settings?tab=account">账户与访问</RouterLink> 生成，仅填入插件后台。</p><div v-if="data.view.astrbot.bound"><code>{{ data.view.astrbot.session }}</code><button class="text-link danger" @click="unbind">解除绑定</button></div></section>
  </aside></div>
  <section class="panel companion-log"><div class="section-heading"><div><h2>最近的小记</h2><p>分享过什么，或为什么保持安静，都能在这里看到。</p></div><button class="icon-button" aria-label="刷新陪伴活动" @click="load"><RefreshCw :size="17" /></button></div><EmptyState v-if="!data.view.activities.length" title="还没有小记" description="开启后，灵犀会在合适的时候来找你。" /><article v-for="a in data.view.activities" :key="a.id"><div class="section-heading"><span :class="['tag',['sent','partial'].includes(a.status)?'green':'neutral']">{{ statuses[a.status]||a.status }}</span><time>{{ date(a.created_at) }}</time></div><p v-if="a.body" class="companion-message">{{ a.body }}</p><p class="companion-reason">{{ reasons[a.reason]||a.reason }}</p><a v-for="s in a.sources" :key="s.id" :href="s.url" target="_blank" rel="noopener noreferrer" class="text-link">{{ s.title }}<ArrowUpRight :size="14" /></a><div class="companion-deliveries"><span v-for="d in a.deliveries" :key="d.channel" :title="d.error">{{ names[d.channel] }} · {{ statuses[d.status]||d.status }}<small v-if="d.error">{{ d.error }}</small></span></div></article></section>
 <FeishuConnect /><QQPrivateRhythm :settings="data.integrations.qq" @changed="load" /><QQOutreachLog :items="data.view.followups||[]" />
 </ResourceState>
</template>
